node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { dispatch } from './src/dispatch.js';
import { registry } from './src/registry.js';
import { handle as mail } from './src/channels/mail.js';
import { handle as audit } from './src/channels/audit.js';
import { handle as legacy } from './src/channels/legacy.js';

const result = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(result).sort(), ['legacy_reachable_from_dispatch', 'registered_files', 'selected_file', 'selected_output', 'target_depends_on_runtime_kind', 'unknown_kind_error']);
assert.deepEqual(Object.keys(registry).sort(), ['audit', 'mail']);
assert.equal(registry.audit, audit);
assert.equal(registry.mail, mail);
assert.ok(!Object.values(registry).includes(legacy));
assert.deepEqual(result.registered_files, ['src/channels/audit.js', 'src/channels/mail.js']);
assert.equal(result.selected_file, 'src/channels/mail.js');
assert.equal(result.selected_output, dispatch({ kind: 'mail', payload: ' Hi ' }));
assert.equal(result.selected_output, 'mail:hi');
assert.throws(() => dispatch({ kind: 'missing', payload: ' Hi ' }), error => error.message === result.unknown_kind_error);
assert.equal(result.target_depends_on_runtime_kind, registry.mail !== registry.audit);
assert.equal(result.legacy_reachable_from_dispatch, false);
console.log('PASS: answer.json structure, registry, dispatch output and unknown-kind error');
NODE

